/**
 *
 * 자주쓰는 부동산 검색조건의 삭제 버튼 클릭시 목록 삭제
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.10.16.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_bmrkDel_onclick =async function(e) {
    const cortAuctnSrchCondCd = dma_srchBmrkSrchCond.get("cortAuctnSrchCondCd");
    const index = $p.getComponentById(this.id).getUserData('ser');
    let cortAuctnMbrsId = "";
    let bmrkSrchSeq = "";
    let mvprpRletDvsCd = "";
    if(cortAuctnSrchCondCd === "0004601"){
        cortAuctnMbrsId = dlt_gdsDtlBmrkSrchCondLst.getCellData(index, 'cortAuctnMbrsId')
        bmrkSrchSeq = dlt_gdsDtlBmrkSrchCondLst.getCellData(index, 'bmrkSrchSeq')
        mvprpRletDvsCd = dlt_gdsDtlBmrkSrchCondLst.getCellData(index, 'mvprpRletDvsCd')
    } else if(cortAuctnSrchCondCd === "0004604"){
        cortAuctnMbrsId = scwin.mvprpBmrkLst[index].cortAuctnMbrsId;
        bmrkSrchSeq = scwin.mvprpBmrkLst[index].bmrkSrchSeq;
        mvprpRletDvsCd = scwin.mvprpBmrkLst[index].mvprpRletDvsCd;
    }
    let delFlag = await pgjUtil.waitConfirm(scglblo.MSG.WARN, scutilo.getMsg(pgjmsg.PGJ.C_0002));
    if (delFlag) {
        dma_deleteBmrkSrchCond.set("cortAuctnMbrsId", cortAuctnMbrsId);
        dma_deleteBmrkSrchCond.set("bmrkSrchSeq", bmrkSrchSeq);
        dma_deleteBmrkSrchCond.set("mvprpRletDvsCd", mvprpRletDvsCd);
        com.executeSubmission(sbm_deleteBmrkSrchCond);
    }
};

/**
 *
 * 자주쓰는 부동산 검색조건 Reload이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.10.16.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.srchBmrkReloadEvent = function(e) {
    dma_srchBmrkSrchCond.set("cortAuctnMbrsId", scwin.lgnMbr);
    dma_srchBmrkSrchCond.set("cortAuctnSrchCondCd", dma_srchBmrkSrchCond.get("cortAuctnSrchCondCd"));
    const cortAuctnSrchCondCd = dma_srchBmrkSrchCond.get("cortAuctnSrchCondCd");
    if(cortAuctnSrchCondCd === "0004601"){
        com.executeSubmission(sbm_selectBmrkSrchCondLst);
    } else if(cortAuctnSrchCondCd === "0004604"){
        com.executeSubmission(sbm_selectMvprpBmrkSrchCondLst);
    }
};


/**
 *
 * 부동산,동산 공고중 시/도(지번) ,시/도(도로명)목록 초기화 메서드
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.02.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.pbancInit = function(flag,dvsCd,rdDvsCd){
    switch (dvsCd) {
        case 'rlet' : // 부동산
            if (rdDvsCd === 'S') {
                sbx_rletAdongSggS.removeAll(true)
                sbx_rletAdongEmd.removeAll(true)
                if (flag === "on") {
                    cbx_rletPbancMidYnS.checkAll(true)
                    scwin.pbancMidFlagS = "Y"
                    pgjUtil.bindSelectBox(pgjUtil.getAdongSdLst("Y","B","A"),sbx_rletAdongSdS,true);
                } else if (flag === "off"){
                    cbx_rletPbancMidYnS.checkAll(false)
                    scwin.pbancMidFlagS = "N"
                    pgjUtil.bindSelectBox(pgjUtil.getAdongSdLst("N","B",""),sbx_rletAdongSdS,true);
                }
            } else if(rdDvsCd === 'R') {
                sbx_rletAdongSggR.removeAll(true)
                sbx_rletAdongRdnm.removeAll(true)
                if (flag === "on") {
                    cbx_rletPbancMidYnR.checkAll(true);
                    scwin.pbancMidFlagR = "Y"
                    pgjUtil.bindSelectBox(pgjUtil.getAdongSdLst("Y","B","BR"),sbx_rletAdongSdR,true);
                } else if (flag === 'off'){
                    cbx_rletPbancMidYnR.checkAll(false);
                    scwin.pbancMidFlagR = "N"
                    pgjUtil.bindSelectBox(pgjUtil.getAdongSdLst("N","B","BR"),sbx_rletAdongSdR,true);
                }
            }
            break;
        case 'mvprp' : //동산
            if (rdDvsCd === 'S') {
                sbx_mvprpAdongSggS.removeAll(true)
                sbx_mvprpAdongEmd.removeAll(true)
                if (flag === "on") {
                    cbx_mvprpPbancMidYnS.checkAll(true)
                    scwin.mvrPbancMidFlagS = "Y"
                    pgjUtil.bindSelectBox(pgjUtil.getAdongSdLst("Y","O","A"),sbx_mvprpAdongSdS,false)
                } else if (flag === "off"){
                    cbx_mvprpPbancMidYnS.checkAll(false)
                    scwin.mvrPbancMidFlagS = "N"
                    pgjUtil.bindSelectBox(pgjUtil.getAdongSdLst("N","O",""),sbx_mvprpAdongSdS,true);
                }
            } else if(rdDvsCd === 'R') {
                sbx_mvprpAdongSggR.removeAll(true)
                sbx_mvprpAdongRdnm.removeAll(true)
                if (flag === "on") {
                    cbx_mvprpPbancMidYnR.checkAll(true);
                    scwin.mvrPbancMidFlagR = "Y"
                    pgjUtil.bindSelectBox(pgjUtil.getAdongSdLst("Y","O","BR"),sbx_mvprpAdongSdR,false);
                } else if (flag === 'off'){
                    cbx_mvprpPbancMidYnR.checkAll(false);
                    scwin.mvrPbancMidFlagR = "N"
                    pgjUtil.bindSelectBox(pgjUtil.getAdongSdLst("N","R",""),sbx_mvprpAdongSdR,true);
                }
            }
            break;
    }
}

/**
 *
 * 부동산 검색조건 목록 데이터 셋팅
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.02.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.rletFormatItemLst = function(itemLst) {
    let result = {};
    // 입찰구분
    let bidDvsCd = itemLst.filter(r=>r.srchTrgtNm === "bidDvsCd");

    // 용도 분류
    let lclDspslGdsLstUsgCd = itemLst.filter(r=>r.srchTrgtNm === "lclDspslGdsLstUsgCd")
    let mclDspslGdsLstUsgCd = itemLst.filter(r=>r.srchTrgtNm === "mclDspslGdsLstUsgCd")
    let sclDspslGdsLstUsgCd = itemLst.filter(r=>r.srchTrgtNm === "sclDspslGdsLstUsgCd")
    // 감정평가금액
    let aeeEvlAmtMin = itemLst.filter(r=>r.srchTrgtNm === "aeeEvlAmtMin")
    let aeeEvlAmtMax = itemLst.filter(r=>r.srchTrgtNm === "aeeEvlAmtMax")
    // 최저매각가격
    let rletLwsDspslPrcMin = itemLst.filter(r=>r.srchTrgtNm === "rletLwsDspslPrcMin")
    let rletLwsDspslPrcMax = itemLst.filter(r=>r.srchTrgtNm === "rletLwsDspslPrcMax")
    // 면적
    let objctArDtsMin = itemLst.filter(r=>r.srchTrgtNm === "objctArDtsMin")
    let objctArDtsMax = itemLst.filter(r=>r.srchTrgtNm === "objctArDtsMax")
    //유찰횟수
    let flbdNcntMin = itemLst.filter(r=>r.srchTrgtNm === "flbdNcntMin");
    let flbdNcntMax = itemLst.filter(r=>r.srchTrgtNm === "flbdNcntMax");
    //최저매각가율
    let lwsDspslPrcRateMin = itemLst.filter(r=>r.srchTrgtNm === "lwsDspslPrcRateMin")
    let lwsDspslPrcRateMax = itemLst.filter(r=>r.srchTrgtNm === "lwsDspslPrcRateMax")
    //특수조건
    let srchCondLst = itemLst.filter(r=>r.srchTrgtNm === "rletDspslSpcCondCd")

    result.bidDvsCd =  bidDvsCd.length !== 0 ? bidDvsCd[0].srchCondVal : '';
    result.lclDspslGdsLstUsgCd =  lclDspslGdsLstUsgCd.length !== 0 ? lclDspslGdsLstUsgCd[0].srchCondVal : '';
    result.mclDspslGdsLstUsgCd =  mclDspslGdsLstUsgCd.length !== 0 ? mclDspslGdsLstUsgCd[0].srchCondVal : '';
    result.sclDspslGdsLstUsgCd =  sclDspslGdsLstUsgCd.length !== 0 ? sclDspslGdsLstUsgCd[0].srchCondVal : '';
    result.aeeEvlAmtMin =  aeeEvlAmtMin.length !== 0 ? aeeEvlAmtMin[0].srchCondVal : '';
    result.aeeEvlAmtMax =  aeeEvlAmtMax.length !== 0 ? aeeEvlAmtMax[0].srchCondVal : '';
    result.rletLwsDspslPrcMin =  rletLwsDspslPrcMin.length !== 0 ? rletLwsDspslPrcMin[0].srchCondVal : '';
    result.rletLwsDspslPrcMax =  rletLwsDspslPrcMax.length !== 0 ? rletLwsDspslPrcMax[0].srchCondVal : '';
    result.objctArDtsMin =  objctArDtsMin.length !== 0 ? objctArDtsMin[0].srchCondVal : '';
    result.objctArDtsMax =  objctArDtsMax.length !== 0 ? objctArDtsMax[0].srchCondVal : '';
    result.flbdNcntMin =  flbdNcntMin.length !== 0 ? flbdNcntMin[0].srchCondVal : '';
    result.flbdNcntMax =  flbdNcntMax.length !== 0 ? flbdNcntMax[0].srchCondVal : '';
    result.lwsDspslPrcRateMin =  lwsDspslPrcRateMin.length !== 0 ? lwsDspslPrcRateMin[0].srchCondVal : '';
    result.lwsDspslPrcRateMax =  lwsDspslPrcRateMax.length !== 0 ? lwsDspslPrcRateMax[0].srchCondVal : '';
    result.srchCondLst = srchCondLst.length !== 0 ? srchCondLst.map( r => r.srchCondVal).join(" ") : '';


    return result
}

/**
 *
 * 부동산 초기화 버튼 클릭시 모든 정보 초기화
 *
 * ============= ============ ==========================
