/**
 *  면적 유효성 체크 메서드
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.18.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.arvldLstnmCheck = function (arMin, arMax) {
    if (arMin.length != 0) {
        if (arMin == "" || scutilo.isEmpty(arMin)
            || Number(arMin) <= 0 || arMin.length > 8) {
            return false;
        }
    }
    if (arMax.length != 0) {
        if (arMax == "" || scutilo.isEmpty(arMax)
            || Number(arMax) <= 0 || arMax.length > 8) {
            return false;
        }
    }
    if (arMin == "" && arMax != "") {
        return false;
    } else if (arMin != "" && arMax == "") {
        return false;
    }
    if (Number(arMin) > Number(arMax)) {
        return false;
    }
    return true;
}

/**
 * 부동산 감정평가액/최저매각각격/입찰횟수/최저매각가율 유효성 체크 메서드
 *
 * type [1: 감정평가액 , 2:최저매각가격, 3: 입찰횟수, 4: 최저매각가율]
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.18.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.selBoxVldLstnmCheck = function (type) {
    const flag = type;
    let minAee = ""
    let maxAee = ""
    switch (flag) {
        case '1':
            minAee = sbx_rletAeePyngEqvalMin.getValue();
            maxAee = sbx_rletAeePyngEqvalMax.getValue();
            break;
        case '2':
            minAee = sbx_rletLwsDspslMin.getValue();
            maxAee = sbx_rletLwsDspslMax.getValue();
            break;
        case '3':
            minAee = sbx_rletFlbdCntMin.getValue();
            maxAee = sbx_rletFlbdCntMax.getValue();
            break;
        case '4':
            minAee = sbx_rletLwsRateMin.getValue();
            maxAee = sbx_rletLwsRateMax.getValue();
            break;
    }
    if (maxAee !== "") {
        if (Number(minAee) > Number(maxAee)) {
            if (flag === '1') sbx_rletAeePyngEqvalMax.setValue(minAee)
            if (flag === '2') sbx_rletLwsDspslMax.setValue(minAee)
            if (flag === '3') sbx_rletFlbdCntMax.setValue(minAee)
            if (flag === '4') sbx_rletLwsRateMax.setValue(minAee)
        }
    }
};

